"""Reference policy compiler built on real FAdo automata.

This is the oracle of the pipeline: the same language semantics as the fast
joint-residual construction in :mod:`compiler.automata`, but every atom is
built as an epsilon NFA and FAdo performs the subset construction, the Boolean
combination and the Brzozowski minimization.  Both compilers hand their minimal
complete machine to one shared canonical writer, so a disagreement is a bug in
one of the two front ends and nothing else.

``compile_rules`` is used by the agent only when the environment asks for the
cross-checked build (``EMICRO_VERIFY=1``); the default path is the fast one.
"""
from FAdo.fa import DFA, NFA

from syntax import PolicyError
from compiler import automata

__all__ = ['compile_rules', 'atom_language', 'combine']


def _chain(n, start, path, width, loop=False):
    """Add a linear path of transitions to the NFA, returning the last state."""
    state = start
    for symbol in path:
        nxt = len(n.States)
        n.addState(nxt)
        n.addTransition(state, symbol, nxt)
        state = nxt
    if loop:
        for symbol in range(width):
            n.addTransition(state, symbol, state)
    return state


def atom_language(kind, path, width):
    """FAdo acceptor of one atom over the column indexes ``0 .. width-1``."""
    if kind == 'match':
        n = NFA()
        n.setSigma(list(range(width)))
        n.addState(0)
        n.setInitial([0])
        last = _chain(n, 0, path, width)
        n.addFinal(last)
        return n.toDFA()
    if kind == 'startswith':
        n = NFA()
        n.setSigma(list(range(width)))
        n.addState(0)
        n.setInitial([0])
        last = _chain(n, 0, path, width, loop=True)
        n.addFinal(last)
        return n.toDFA()
    # endswith / contains share the "anything before" prefix.
    n = NFA()
    n.setSigma(list(range(width)))
    n.addState(0)
    n.setInitial([0])
    for symbol in range(width):
        n.addTransition(0, symbol, 0)
    body = len(n.States)
    n.addState(body)
    n.addTransition(0, '@epsilon', body)
    last = _chain(n, body, path, width, loop=kind == 'contains')
    n.addFinal(last)
    return n.toDFA()


def _complete(d, width):
    """Turn an FAdo DFA into a complete machine with dense integer states."""
    d.complete()
    states = list(d.States)
    if d.Initial not in states:
        states.append(d.Initial)
    index = {state: position for position, state in enumerate(states)}
    rows = []
    flags = []
    for state in states:
        row = []
        for symbol in range(width):
            try:
                target = d.delta[state][symbol]
            except KeyError:
                target = None
            row.append(index[target] if target is not None else index.get(state, 0))
        rows.append(row)
        flags.append(state in d.Final)
    return index[d.Initial], rows, flags


def combine(rules, width, name_to_column):
    """Union the allow rules, union the drop rules and subtract them."""
    atoms = {}

    def language(predicate):
        kind = predicate[0]
        if kind in ('match', 'startswith', 'endswith', 'contains'):
            key = (kind, tuple(name_to_column[name] for name in predicate[1]))
            machine = atoms.get(key)
            if machine is None:
                machine = atom_language(key[0], key[1], width)
                atoms[key] = machine
            return machine
        if kind == 'not':
            return ~language(predicate[1])
        left = language(predicate[1])
        right = language(predicate[2])
        return (left | right) if kind == 'or' else (left & right)

    allow = None
    deny = None
    for predicate, allowed in rules:
        machine = language(predicate)
        if allowed:
            allow = machine if allow is None else (allow | machine)
        else:
            deny = machine if deny is None else (deny | machine)
    if allow is None:
        empty = DFA()
        empty.setSigma(list(range(width)))
        empty.addState(0)
        empty.setInitial(0)
        for symbol in range(width):
            empty.addTransition(0, symbol, 0)
        allow = empty
    result = allow if deny is None else (allow & ~deny)
    result.complete()
    return result.minimal()


def compile_rules(rules, columns, name_to_column):
    """Canonical image of ``rules`` computed entirely with FAdo automata."""
    width = len(columns)
    if width <= 0:
        raise PolicyError('empty registry')
    for predicate, _ in rules:
        _depth_ok(predicate, 1)
    minimal = combine(rules, width, name_to_column)
    start, rows, flags = _complete(minimal, width)
    if start != 0:
        order = list(range(len(rows)))
        order.remove(start)
        order.insert(0, start)
        position = {old: new for new, old in enumerate(order)}
        rows = [[position[target] for target in rows[old]] for old in order]
        flags = [flags[old] for old in order]
    image = automata._canonical(len(rows), rows, flags, width)
    if image['rows_count'] > automata.MAX_ROWS:
        raise automata.TooBig('image rows')
    return image


def _depth_ok(predicate, depth):
    if depth > 16:
        raise PolicyError('predicate depth')
    kind = predicate[0]
    if kind in ('and', 'or', 'not'):
        for child in predicate[1:]:
            _depth_ok(child, depth + 1)
